public final class FocusAudit {
 private static void check(String n,boolean ok,Object detail){ServerAudit.check("focus: "+n,ok,detail);}
 private static ItemStack item(String id){return EMTRecipes.stack(id);}
 private static ItemStack charged(String id,double eu){var s=item(id);ElectricItem.manager.charge(s,eu,10,true,false);return s;}
 public static void run(ServerLevel l,BlockPos base){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(l);p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();for(var slot:EquipmentSlot.values())p.setItemSlot(slot,ItemStack.EMPTY);p.removeAllEffects();p.setPos(base.getX()+90.5,base.getY()+2,base.getZ()+.5);p.setXRot(0);p.setYRot(0);p.setShiftKeyDown(false);
  var wand=item("tc4modern:wand");for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,10,true);p.setItemInHand(InteractionHand.MAIN_HAND,wand);
  for(var entry:EMTItems.FOCI.entrySet()){var s=new ItemStack(entry.getValue().get());FociContent.setFocus(wand,s);check(entry.getKey()+" native wand accepts and persists focus",FociContent.getFocus(wand) instanceof EMTFocus f&&f.kind==((EMTFocus)s.getItem()).kind,FociContent.getFocusItem(wand));}
  FociContent.setFocus(wand,item("emt:focus_charge"));var boots=charged("emt:electric_boots_traveller",99999.5);var helmet=charged("emt:nano_goggles",0);p.setItemSlot(EquipmentSlot.FEET,boots);p.setItemSlot(EquipmentSlot.HEAD,helmet);int before=WandData.get(wand,Aspect.AIR);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);check("charge focus distributes fractional64EU armor first",ElectricItem.manager.getCharge(boots)==100000&&ElectricItem.manager.getCharge(helmet)==63.5,ElectricItem.manager.getCharge(helmet));check("native wand consumes all six vis aspects",WandData.get(wand,Aspect.AIR)<before&&WandData.get(wand,Aspect.FIRE)<before,WandData.get(wand,Aspect.AIR));
  p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);before=WandData.get(wand,Aspect.AIR);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);check("full electric items do not waste charging vis",WandData.get(wand,Aspect.AIR)==before,"unchanged");
  var upgraded=item("emt:focus_charge");var focus=(EMTFocus)upgraded.getItem();check("native manipulator upgrades accept potency and frugal",Arrays.equals(focus.getPossibleUpgradesByRank(upgraded,1),new int[]{0,1})&&focus.applyUpgrade(upgraded,0,1)&&focus.applyUpgrade(upgraded,1,2),Arrays.toString(focus.getAppliedUpgrades(upgraded)));FociContent.setFocus(wand,upgraded);var empty=charged("emt:nano_boots_traveller",0);p.setItemSlot(EquipmentSlot.FEET,empty);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);check("potency increases native charge output to70.4EU",Math.abs(ElectricItem.manager.getCharge(empty)-70.4)<.0001,ElectricItem.manager.getCharge(empty));p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);
  var legs=charged("ic2:quantum_leggings",100000);p.setItemSlot(EquipmentSlot.LEGS,legs);FociContent.setFocus(wand,item("emt:focus_wand_charging"));before=WandData.get(wand,Aspect.AIR);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);check("wand charging starts real native use lifecycle",p.isUsingItem()&&FociContent.usingFocus(p),"using");FociContent.useTick(wand,p,100);check("reference leggings supply40000EU for1vis each",ElectricItem.manager.getCharge(legs)==60000&&WandData.get(wand,Aspect.AIR)==before+100,ElectricItem.manager.getCharge(legs));FociContent.release(wand,l,p,99);p.stopUsingItem();check("native wand release clears focus state",!FociContent.usingFocus(p),"released");ElectricItem.manager.discharge(legs,59999,10,true,false,false);before=WandData.get(wand,Aspect.AIR);FociContent.getFocus(wand).onUsingFocusTick(wand,p,1);check("insufficient leggings EU is atomic",ElectricItem.manager.getCharge(legs)==1&&WandData.get(wand,Aspect.AIR)==before,"no partial debit");p.setItemSlot(EquipmentSlot.LEGS,ItemStack.EMPTY);
  FociContent.setFocus(wand,item("emt:focus_energy_ball"));var chest=charged("emt:infused_quantum_chestplate",5119);p.setItemSlot(EquipmentSlot.CHEST,chest);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);check("energy ball requires full5120EU without partial loss",ElectricItem.manager.getCharge(chest)==5119,ElectricItem.manager.getCharge(chest));ElectricItem.manager.charge(chest,1,10,true,false);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);var balls=l.getEntitiesOfClass(EntityEnergyBall.class,p.getBoundingBox().inflate(2));check("energy ball spawns once and debits5120EU",balls.size()==1&&ElectricItem.manager.getCharge(chest)==0,balls.size());for(var ball:balls)ball.discard();p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);
  var pos=base.offset(90,2,30);l.setBlock(pos,Blocks.GLASS.defaultBlockState(),3);var laser=new EntityLaser(l,p);laser.setPos(Vec3.atCenterOf(pos.north(2)));laser.setDeltaMovement(0,0,1);l.addFreshEntity(laser);for(int i=0;i<5&&!laser.isRemoved();i++)laser.tick();check("laser actual block collision explodes and removes projectile",laser.isRemoved()&&l.isEmptyBlock(pos),l.getBlockState(pos));
  var ball=new EntityEnergyBall(l,p);ball.setPos(Vec3.atCenterOf(base.offset(90,5,50)));ball.activate();var pig=new net.minecraft.world.entity.animal.Pig(EntityType.PIG,l);pig.setPos(ball.position().add(2,0,0));l.addFreshEntity(pig);l.addFreshEntity(ball);ball.tick();check("stationary energy ball damages nearby mobs by radius",pig.getHealth()<10,pig.getHealth());var saved=new net.minecraft.nbt.CompoundTag();ball.saveWithoutId(saved);var loaded=new EntityEnergyBall(EMTEntities.ENERGY_BALL.get(),l);loaded.load(saved);check("energy ball active state survives save",loaded.inTile(),"persisted");for(int i=0;i<59&&!ball.isRemoved();i++)ball.tick();check("energy ball expires after60active ticks",ball.isRemoved(),ball.tickCount);pig.discard();
  FociContent.setFocus(wand,item("emt:focus_shield"));p.setItemInHand(InteractionHand.MAIN_HAND,wand);before=WandData.get(wand,Aspect.ORDER);FociContent.wandUse(l,p,InteractionHand.MAIN_HAND);var shields=l.getEntitiesOfClass(EntityShield.class,p.getBoundingBox().inflate(4));check("shield native focus creates following collider",shields.size()==1&&shields.getFirst().owner()==p&&shields.getFirst().getBoundingBox().getXsize()==4,"shield");p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.POISON,100));FociContent.useTick(wand,p,100);check("shield ticks remove effects and consume vis",!p.hasEffect(net.minecraft.world.effect.MobEffects.POISON)&&WandData.get(wand,Aspect.ORDER)<before,"tick");FociContent.release(wand,l,p,99);p.stopUsingItem();for(var shield:shields){shield.tick();check("shield disappears after native release",shield.isRemoved(),"released");}
  var shard=TC4Addons.tagIngredient(item("tc4modern:air_shard"),net.minecraft.resources.ResourceLocation.parse("tc4modern:shards"));check("native infusion matcher accepts any original shard",thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(item("tc4modern:water_shard"),shard)&&!thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(new ItemStack(Items.DIAMOND),shard),"tag");var sapling=TC4Addons.tagIngredient(new ItemStack(Items.OAK_SAPLING),net.minecraft.resources.ResourceLocation.withDefaultNamespace("saplings"));check("native infusion matcher accepts every sapling",thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(new ItemStack(Items.SPRUCE_SAPLING),sapling),"spruce");
  var recipe=TC4Addons.infusionRecipes().stream().filter(r->r.key().equals("emt:chargeFocus")).findFirst().orElseThrow();var components=new ArrayList<>(recipe.componentStacks());for(int i=0;i<components.size();i++)if(NoteData.tag(components.get(i)).contains("TC4IngredientTag"))components.set(i,item("tc4modern:water_shard"));check("actual infusion recipe matches mixed wildcard components",InfusionItemRecipes.match(components,new ItemStack(recipe.central().get()),Set.of(recipe.research()))==recipe,"chargeFocus");var fishRecipe=InfusionItemRecipes.all().stream().filter(r->r.key().equals("BootsTraveller")).findFirst().orElseThrow();check("base traveller boots still accept native raw fish alternatives",thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(new ItemStack(Items.SALMON),fishRecipe.componentStacks().get(5)),"salmon");var water=InfusionItemRecipes.all().stream().filter(r->r.key().equals("CoreAlchemy")).findFirst().orElseThrow().componentStacks().get(1);var awkward=net.minecraft.world.item.alchemy.PotionContents.createItemStack(Items.POTION,net.minecraft.world.item.alchemy.Potions.AWKWARD);check("base infusion still rejects wrong potion components",!thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(awkward,water),"water only");
  var matrixPos=base.offset(90,0,90);l.setBlock(matrixPos,InfusionContent.MATRIX.get().defaultBlockState(),3);var matrix=(InfusionContent.MatrixEntity)l.getBlockEntity(matrixPos);ResearchProgress.add(p.getPersistentData(),recipe.research());var match=matrix.findRecipe(components,new ItemStack(recipe.central().get()),p);check("native matrix carries wildcard ingredients into actual crafting",match!=null&&match.components().stream().anyMatch(s->NoteData.tag(s).contains("TC4IngredientTag")),"matrix");if(match!=null){matrix.logic.recipeIngredients=new ArrayList<>(match.components());matrix.logic.recipeEssentia=recipe.aspects().copy();var nbt=new net.minecraft.nbt.CompoundTag();matrix.logic.save(nbt,l.registryAccess());var restored=new thaumcraft.common.tiles.infusion.InfusionMatrixLogic();restored.load(nbt,l.registryAccess());check("matrix save preserves wildcard consumption after reload",restored.recipeIngredients.stream().filter(s->NoteData.tag(s).contains("TC4IngredientTag")).allMatch(s->thaumcraft.common.tiles.infusion.InfusionMatrixLogic.sameIngredient(item("tc4modern:fire_shard"),s)),"reload");}l.setBlock(matrixPos,Blocks.AIR.defaultBlockState(),3);
  p.getInventory().clearContent();for(var slot:EquipmentSlot.values())p.setItemSlot(slot,ItemStack.EMPTY);
 }
}
